SELECT * FROM reviews
WHERE product_id = #{productId}
ORDER BY created_at DESC

SELECT COALESCE(AVG(rating), 0)
FROM reviews
WHERE product_id = #{productId}

SELECT COUNT(*)
FROM reviews
WHERE product_id = #{productId}

SELECT COUNT(*)
FROM order_items oi
JOIN orders o ON oi.order_id = o.id
WHERE o.user_id = #{userId}
AND oi.product_id = #{productId}
